#!/usr/bin/env python3
# luxarch:release-actions-collected hook v1 - DO NOT edit this file - it is emitted by `luxarch --emit hooks`; re-emit to update.
"""A release consumes every release action its commit carries before it is tagged or built.

An issue whose work needs a step or a heads-up when it ships records it as it closes, twice: the
`release-action` label and a `Release: <the step>` line on the issue in LuxPM, and the file
`release-actions/<KEY>.md` at the repo's root, committed with the work (`release-action-close`).
The file travels with the commit, so the release that holds the work holds its step (the
Changesets pattern). The release moves each file into its change log's `Release actions` section
and deletes it (`--doc FLEET-RELEASE-PROCESS` §3a).

PreToolUse(Bash). A release is a `git tag` that creates a `v<version>` tag (not `-l`, `-d`, `-v`
or `-n`), or a `make release` that is no dry run (`-n`, `--dry-run`, `--just-print`, `--recon`,
`-q`); `-C <dir>` and a `VERSION=` argument are read as make reads them. Each simple command is
read as the shell runs it, a `cd` before it moving where it runs. For each:

1. The repo is the checkout the command runs in. The version is the tag's; a tag name the shell
   computes right after its `v` (`v$(cat VERSION)`, `v${VERSION}`), and a `make release`, take the
   `VERSION=` argument or the repo's `VERSION` file. The release commit is the commit a literal tag
   name is followed by, else HEAD; one git cannot resolve is denied.
2. The release commit holds nothing under `release-actions/`: each file is consumed before the
   release, and a path the convention does not name (`ab-7.md`, `AB-7.MD`, a subfolder) is held
   all the same.
3. Every action consumed since the earlier releases is named by key in this version's change log
   `Release actions` section. Consumed is a file removed by a commit that also edits a change log
   (the release step's commit); a file removed with no change-log edit is withdrawn and owes
   nothing. Since the earlier releases is every commit of the release commit's history that no
   merged `v*` tag other than this version holds (for a final version, no merged final tag:
   what its pre-releases consumed is named again), so a hotfix merged back, or a tag added later
   on an old commit, does not reopen what a release already consumed.
4. The change log is read from the release commit, never the working copy: every
   `change_logs/<version>.md` it holds outside `tests/` and `fixtures/` (an app's), else the
   `## <version>` entry of its root `CHANGELOG.md` (a guard's), which runs to the next version's
   `##` heading. Its `Release actions` section is a `Release actions` heading of any level (`#`
   or setext) to the next heading; fenced code is no heading and no section.

Denied: a release commit that still holds anything under `release-actions/`, a change log that
leaves out an action consumed since the earlier releases, and a release commit git cannot read.
Reads only git: no tracker, no network.

A safety gate for a release, so it fails CLOSED on an event it cannot read (`guarded`).
"""

from __future__ import annotations

import os
import re
import subprocess
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).parent))
from _cmdtext import (
    git_call,
    guarded,
    load_event,
    simple_commands,
    text_field,
    tool_input,
)
from _ledger import tree_dir
from _release_actions import ACTIONS_DIR, action_key

_TAG_NOT_CREATING = {"-l", "--list", "-d", "--delete", "-v", "--verify", "-n"}
_RELEASE_TAG = re.compile(r"v(\d[0-9A-Za-z.+-]*)")
_COMPUTED = re.compile(r"v[$`]")  # a version the shell computes: `v$(cat VERSION)`
_MAKE_VALUE = {"-C", "-f", "-I", "-o", "-W", "--directory", "--file", "--makefile",
               "--include-dir", "--old-file", "--assume-old", "--what-if", "--new-file",
               "--assume-new", "--jobs", "--load-average", "-l"}  # fmt: skip
_MAKE_DIR = {"-C", "--directory"}
_MAKE_DRY = {"-n", "--dry-run", "--just-print", "--recon", "-q", "--question"}
_NOT_A_CHANGE_LOG = {"tests", "test", "fixtures", "node_modules"}
_FENCE = re.compile(r"^[ \t]{0,3}(`{3,}|~{3,})")
# a paragraph line over `===`/`---`; a list item or quote over `---` is a rule, not a heading
_SETEXT = re.compile(
    r"^(?![ \t]*(?:[-*+>]|\d+[.)])[ \t])([^\n]*\S[^\n]*)\n[ \t]{0,3}(=+|-+)[ \t]*$",
    re.MULTILINE,
)
_CHANGE_LOG_PATH = re.compile(r"(?:^|/)(?:CHANGELOG\.md|change_logs/[^/]+\.md)$")
_SECTION = re.compile(
    r"^#{1,6}[ \t]+release[ \t]+actions\b.*$", re.IGNORECASE | re.MULTILINE
)
_HEADING = re.compile(r"^#{1,6}[ \t]", re.MULTILINE)
_GIT_TIMEOUT = 10
# a NAME, not an inline `except (A, B)`: its formatting differs per Python target (PEP 758)
_GIT_ERRORS = (OSError, subprocess.SubprocessError)

Release = tuple[Path, str, str]  # (where it runs, version or '', release commit)


def _run_git(root: Path, *args: str) -> tuple[int, str]:
    try:
        out = subprocess.run(
            ["git", "-C", str(root), *args],
            capture_output=True,
            timeout=_GIT_TIMEOUT,
            check=False,
        )
    except _GIT_ERRORS:
        return 1, ""
    return out.returncode, out.stdout.decode("utf-8", "replace")


def _git(root: Path, *args: str) -> str:
    rc, out = _run_git(root, *args)
    return out if rc == 0 else ""


def _make_release(argv: tuple[str, ...]) -> tuple[str, str] | None:
    """(directory, VERSION=) of a `make … release …` that runs, or None."""
    where, version, dry = "", "", False
    targets: list[str] = []
    i = 1
    while i < len(argv):
        w = argv[i]
        i += 1
        if w == "--":
            targets += argv[i:]
            break
        name, eq, value = w.partition("=")
        if w.startswith("--"):
            dry = dry or name in _MAKE_DRY
            if name in _MAKE_VALUE and not eq:
                value, i = (argv[i] if i < len(argv) else ""), i + 1
            if name in _MAKE_DIR:
                where = os.path.join(where, value)
            continue
        if w.startswith("-") and len(w) > 1:
            for j, ch in enumerate(w[1:]):
                flag = "-" + ch
                dry = dry or flag in _MAKE_DRY
                if flag in _MAKE_VALUE:
                    if j < len(w) - 2:
                        value = w[j + 2 :]
                    elif flag in ("-j", "-l"):
                        value = ""
                    else:
                        value, i = (argv[i] if i < len(argv) else ""), i + 1
                    if flag in _MAKE_DIR:
                        where = os.path.join(where, value)
                    break
            continue
        if eq and re.fullmatch(r"[A-Za-z_][A-Za-z0-9_]*", name):
            if name == "VERSION":
                version = value
            continue
        targets.append(w)
    return (where, version) if "release" in targets and not dry else None


def _releases(cmd: str, base: Path) -> list[Release]:
    """Each release `cmd` runs, in order."""
    out: list[Release] = []
    cwd = base
    for sc in simple_commands(cmd):
        argv = sc.argv
        if not argv:
            continue
        prog = os.path.basename(argv[0])
        if prog == "cd" and len(argv) == 2:
            cwd = Path(os.path.normpath(cwd / argv[1]))
            continue
        if prog in ("make", "gmake"):
            found = _make_release(argv)
            if found:
                out.append((Path(os.path.normpath(cwd / found[0])), found[1], "HEAD"))
            continue
        g = git_call(sc)
        if g is None or g.sub != "tag" or _TAG_NOT_CREATING & set(g.flags):
            continue
        name = g.positionals[0] if g.positionals else ""
        m = _RELEASE_TAG.fullmatch(name)
        if m or _COMPUTED.match(name):
            # a computed name is split into words here, so only a literal one names its commit
            commit = g.positionals[1] if m and len(g.positionals) > 1 else "HEAD"
            where = Path(os.path.normpath(cwd / g.cwd))
            out.append((where, m.group(1) if m else "", commit))
    return out


def _show(root: Path, commit: str, path: str) -> str | None:
    rc, out = _run_git(root, "show", f"{commit}:{path}")
    return out if rc == 0 else None


def _unfenced(text: str) -> str:
    """`text` with every fenced code block's lines emptied: a `#` there is no heading."""
    out, fence = [], ""
    for line in text.split("\n"):
        m = _FENCE.match(line)
        if fence:
            if m and m.group(1)[0] == fence[0] and len(m.group(1)) >= len(fence):
                fence = ""
            out.append("")
            continue
        if m:
            fence = m.group(1)
            out.append("")
            continue
        out.append(line)
    return "\n".join(out)


def _atx(text: str) -> str:
    """Setext headings (a line over `===` or `---`) rewritten as `#` headings."""
    return _SETEXT.sub(
        lambda m: ("# " if m.group(2)[0] == "=" else "## ") + m.group(1).strip(), text
    )


def _entry(whole: str, version: str) -> str | None:
    """A CHANGELOG.md's `## <version>` entry, to the next version's `##` heading."""
    text = _unfenced(whole)
    head = re.search(
        rf"^##[ \t]+v?{re.escape(version)}(?![0-9A-Za-z.+-]).*$", text, re.MULTILINE
    )
    if not head:
        return None
    rest = text[head.end() :]
    nxt = re.search(r"^##[ \t]+v?\d", rest, re.MULTILINE)
    return text[head.start() : head.end() + (nxt.start() if nxt else len(rest))]


def _change_logs(root: Path, version: str, commit: str) -> list[str]:
    """This version's change logs as the release commit holds them."""
    texts = []
    for rel in _git(root, "ls-tree", "-r", "--name-only", commit).splitlines():
        parts = rel.split("/")
        if len(parts) < 2 or parts[-2] != "change_logs" or parts[-1] != f"{version}.md":
            continue
        if _NOT_A_CHANGE_LOG & set(parts[:-2]):
            continue
        text = _show(root, commit, rel)
        if text is not None:
            texts.append(_unfenced(text))
    if texts:
        return texts
    whole = _show(root, commit, "CHANGELOG.md")
    entry = _entry(whole, version) if whole else None
    return [entry] if entry is not None else []


def _section(text: str) -> str | None:
    """The text of a change log's `Release actions` section(s), each to the next heading."""
    text = _atx(_unfenced(text))
    parts = []
    for m in _SECTION.finditer(text):
        body = text[m.end() :]
        nxt = _HEADING.search(body)
        parts.append(body[: nxt.start() if nxt else len(body)])
    return "\n".join(parts) if parts else None


def _named(key: str, text: str) -> bool:
    return re.search(rf"(?<![A-Za-z0-9-]){re.escape(key)}(?![0-9])", text) is not None


def _earlier(root: Path, version: str, commit: str) -> list[str]:
    """Every `v*` tag merged into `commit` that is an earlier release: not `v<version>` and, for a
    final version, no pre-release."""
    listing = _git(
        root,
        "for-each-ref",
        f"--merged={commit}",
        "--format=%(refname:strip=2)",
        "refs/tags/v[0-9]*",
    )
    return [
        n
        for n in listing.split()
        if n != f"v{version}" and not ("-" in n and "-" not in version)
    ]


def _consumed(root: Path, commit: str, earlier: list[str]) -> list[str]:
    """Keys whose file a commit since the earlier releases removed while editing a change log."""
    shas = _git(
        root,
        "log",
        "--format=%H",
        "--diff-filter=D",
        commit,
        "--not",
        *earlier,
        "--",
        f"{ACTIONS_DIR}/",
    ).split()
    out: list[str] = []
    for sha in shas:
        changed = _git(
            root, "show", "--format=", "--name-status", "--no-renames", sha
        ).splitlines()
        paths = [line.split("\t")[-1] for line in changed if "\t" in line]
        if not any(_CHANGE_LOG_PATH.search(p) for p in paths):
            continue  # removed with no change-log edit: withdrawn, not consumed
        out += [
            k
            for line in changed
            if line.startswith("D\t") and (k := action_key(line.split("\t", 1)[1]))
        ]
    return list(dict.fromkeys(out))


def _faults(release: Release) -> list[str]:
    where, version, commit = release
    top = _git(where, "rev-parse", "--show-toplevel").strip()
    if not top:
        return []
    root = Path(top)
    if not version:
        try:
            version = (root / "VERSION").read_text(encoding="utf-8").strip()
        except OSError:
            return [
                f"{root.name}: no VERSION file, so the release's version is unknown"
            ]
    if not _git(
        root, "rev-parse", "--verify", "--quiet", f"{commit}^{{commit}}"
    ).strip():
        return [
            f"{root.name}: `{commit}` names no commit git can read, so its release cannot be judged"
        ]
    held = _git(
        root, "ls-tree", "-r", "--name-only", commit, "--", f"{ACTIONS_DIR}/"
    ).split("\n")
    out = [
        f"{commit} still holds {path}: move its step into this version's `Release actions` "
        "section, `git rm` the file, and commit both"
        + (
            ""
            if action_key(path)
            else f" (name a file `{ACTIONS_DIR}/<KEY>.md`, KEY as `AB-12`)"
        )
        for path in held
        if path.strip()
    ]
    consumed = _consumed(root, commit, _earlier(root, version, commit))
    if not consumed:
        return out
    logs = _change_logs(root, version, commit)
    sections = [s for s in (_section(t) for t in logs) if s is not None]
    text = "\n".join(sections)
    missing = [k for k in consumed if not _named(k, text)]
    if missing and not logs:
        out.append(
            f"{version}: {commit} holds no change log for this version (no committed "
            f"change_logs/{version}.md, no `## {version}` entry in CHANGELOG.md), and it "
            f"consumed the release actions of {', '.join(missing)}"
        )
    elif missing:
        out += [
            f"{k}: its {ACTIONS_DIR}/{k}.md was consumed since the last release, and this "
            "version's `Release actions` section does not name it"
            for k in missing
        ]
    return out


def main() -> int:
    ev = load_event()
    if str(ev.get("tool_name") or "") != "Bash":
        return 0
    cmd = text_field(tool_input(ev), "command")
    cwd = text_field(ev, "cwd")
    faults: list[str] = []
    for release in dict.fromkeys(_releases(cmd, Path(cwd) if cwd else tree_dir())):
        faults += _faults(release)
    if not faults:
        return 0
    print(
        "DENIED by release-actions-collected: a release consumes every release action its commit "
        "carries.\n"
        + "".join(f"  - {f}\n" for f in faults)
        + "Each `release-actions/<KEY>.md` is a step or a heads-up this release owes: do it, list\n"
        "it as `- <KEY>: <the step>` under a `Release actions` heading in the version's change log\n"
        "(an app's change_logs/<version>.md, a guard's CHANGELOG.md entry), `git rm` the file,\n"
        "commit, then run this again (--doc FLEET-RELEASE-PROCESS §3a).",
        file=sys.stderr,
    )
    return 2


if __name__ == "__main__":
    sys.exit(guarded(main, "release-actions-collected"))
